<span class="line"><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">import</span><span style="--shiki-light:#C18401;--shiki-dark:#E5C07B;"> io.micrometer.core.instrument.MeterRegistry</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">;</span></span>
